    @Override
    public void log(String message) {
        System.out.println("Logging to file: " + message);
    }
}

// ConsoleLogger implementation
public class ConsoleLogger implements Logger {
    @Override
    public void log(String message) {
        System.out.println("Logging to console: " + message);
    }
}
